package za.co.lepetse.admin;
import org.junit.jupiter.api.Test;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.text.PDFTextStripper;
import java.util.*;
import java.nio.file.*;
import static org.assertj.core.api.Assertions.*;
class CustomerQuotationPdfTest {
 Map<String,Object> sample(){var q=new HashMap<String,Object>();q.put("reference","LQ-000001-R1");q.put("created_at","2026-11-24T10:00:00Z");q.put("valid_until","2026-12-08");q.put("customer",Map.of("requestReference","RFQ-20261124-000001","buyer",Map.of("organisation","TEST — Admin workflow","contact","Test Buyer","email","admin-test@example.invalid"),"deliveries",List.of(Map.of("street","1 Test Road","suburb","Test suburb","city","Johannesburg","province","Gauteng","postal_code","2000"))));q.put("items",List.of(item("BIC Crystal blue ballpoint pen",75,"5.54","415.50"),item("Staedtler glue stick 40 g",12,"13.92","167.04"),item("Butterfly A4 show file — 20 pockets",10,"16.58","165.80")));q.put("subtotal","748.34");q.put("delivery_ex_vat","500.00");q.put("vatTotal","174.77");q.put("total","1423.11");q.put("terms","Prices are subject to the confirmed specification and agreed delivery arrangements.");return q;}
 Map<String,Object> item(String description,int qty,String price,String total){return Map.of("description",description,"quantity",qty,"ordering_unit","Each","unit_price_ex_vat",price,"lineTotal",total);}
 @Test void matchesPreviewSectionsAndAmounts()throws Exception{byte[] bytes=CustomerQuotationPdf.render(sample());Files.write(Path.of("target/quotation-layout-preview.pdf"),bytes);try(var pdf=Loader.loadPDF(bytes)){assertThat(pdf.getNumberOfPages()).isEqualTo(1);String text=new PDFTextStripper().getText(pdf);assertThat(text).contains("CUSTOMER","DELIVERY ADDRESS","QUOTATION DETAILS","24 Nov 2026","08 Dec 2026","Qty / unit","Price excl. VAT","Total excl. VAT","Goods excl. VAT","Transport excl. VAT","R 1 423,11","Terms","Admin@lepetse.co.za","084 030 3307 or 063 140 5757","Banking details","LEPETSE BUSINESS ENTERPRISE AND PROJECT","FNB","Account number:","IRENE MALL SERVICE CENTRE","210529","FIRNZAJJ").doesNotContain("VAT rate:","Supplier","markup");}}
 @Test void paginatesLongDescriptionsAndTermsWithoutDroppingContent()throws Exception{var q=sample();var items=new ArrayList<Map<String,Object>>();for(int i=0;i<75;i++)items.add(item("Item "+i+" detailed customer specification ".repeat(8),1,"1.00","1.00"));q.put("items",items);q.put("terms","Delivery arrangements and agreed terms. ".repeat(180)+"END-OF-TERMS");try(var pdf=Loader.loadPDF(CustomerQuotationPdf.render(q))){assertThat(pdf.getNumberOfPages()).isGreaterThan(3);String text=new PDFTextStripper().getText(pdf);assertThat(text).contains("Item 0","Item 74","END-OF-TERMS");for(var page:pdf.getPages())assertThat(page.getMediaBox().getWidth()).isGreaterThan(page.getMediaBox().getHeight());}}
 @Test void preservesMultipleLongDeliveryAddresses()throws Exception{var q=sample();var locations=new ArrayList<Map<String,String>>();for(int i=0;i<35;i++)locations.add(Map.of("street","Location "+i+" Long Street","suburb","Test suburb","city","Johannesburg","province","Gauteng","postal_code","2000"));q.put("customer",Map.of("buyer",Map.of("organisation","Long address customer","contact","Buyer","email","buyer@example.invalid"),"requestReference","RFQ-LONG","deliveries",locations));try(var pdf=Loader.loadPDF(CustomerQuotationPdf.render(q))){assertThat(new PDFTextStripper().getText(pdf)).contains("Location 0","Location 34","BIC Crystal blue ballpoint pen","Terms");assertThat(pdf.getNumberOfPages()).isGreaterThan(1);}}
}
